import type { BaseInteractionContext } from "honocord";

/** Custom Hono variables, set by the middleware in `index.ts`. */
export interface Variables {
  receivedAt: number;
}

/**
 * Interaction context typed with the Worker bindings generated by `wrangler types`
 * (`Env` from worker-configuration.d.ts) and our custom variables.
 */
export type Context = BaseInteractionContext<Env, Variables>;
